function creerFilePriorite() {
  const heap = [];

  function echanger(i, j) {
    [heap[i], heap[j]] = [heap[j], heap[i]];
  }

  function remonter(index) {
    while (index > 0) {
      const parent = Math.floor((index - 1) / 2);
      if (heap[parent].priorite > heap[index].priorite) {
        echanger(parent, index);
        index = parent;
      } else {
        break;
      }
    }
  }

  function descendre(index) {
    const taille = heap.length;
    while (true) {
      let plusPetit = index;
      const gauche = 2 * index + 1;
      const droite = 2 * index + 2;
      if (gauche < taille && heap[gauche].priorite < heap[plusPetit].priorite) {
        plusPetit = gauche;
      }
      if (droite < taille && heap[droite].priorite < heap[plusPetit].priorite) {
        plusPetit = droite;
      }
      if (plusPetit !== index) {
        echanger(index, plusPetit);
        index = plusPetit;
      } else {
        break;
      }
    }
  }

  return {
    enqueue(val, priorite) {
      heap.push({ val, priorite });
      remonter(heap.length - 1);
    },
    dequeue() {
      if (heap.length === 0) return undefined;
      if (heap.length === 1) return heap.pop().val;
      const min = heap[0].val;
      heap[0] = heap.pop();
      descendre(0);
      return min;
    },
    taille() {
      return heap.length;
    }
  };
