function creerCircuitBreaker(fn, seuil, delaiResetMs) {
  let state = 'CLOSED';
  let failures = 0;
  let timer = null;

  function tripToOpen() {
    state = 'OPEN';
    failures = 0;
    timer = setTimeout(() => {
      state = 'HALF_OPEN';
      timer = null;
    }, delaiResetMs);
  }

  return async function(...args) {
    if (state === 'OPEN') {
      throw new Error('Circuit breaker is OPEN');
    }

    try {
      const result = await fn(...args);

      if (state === 'HALF_OPEN') {
        state = 'CLOSED';
      }
      failures = 0;

      return result;
    } catch (err) {
      failures++;

      if (state === 'HALF_OPEN' || failures >= seuil) {
        tripToOpen();
      }

      throw err;
    }
  };
}
