function dijkstra(graphe, depart) {
  const distances = {};
  const visite = new Set();
  const priorite = [];

  for (const noeud in graphe) {
    distances[noeud] = Infinity;
  }
  distances[depart] = 0;
  priorite.push([depart, 0]);

  while (priorite.length > 0) {
    priorite.sort((a, b) => a[1] - b[1]);
    const [current, distCurrent] = priorite.shift();

    if (visite.has(current)) continue;
    visite.add(current);

    if (graphe[current]) {
      for (const voisin in graphe[current]) {
        const poids = graphe[current][voisin];
        const nouvelleDist = distCurrent + poids;
        if (nouvelleDist < distances[voisin]) {
          distances[voisin] = nouvelleDist;
          priorite.push([voisin, nouvelleDist]);
        }
      }
    }
  }

  return distances;
}
